//! The Rayleigh path reflectance against the transfer equation, and libRadtran's distance from it.
//!
//! What decides [`path_reflectance`] here is `derivations/slab_doubling.jl`: the conservative
//! Rayleigh slab solved by doubling and adding at the 512 geometries and depths of the libRadtran
//! table, written to `fixtures/rayleigh_doubling.txt` (the gate at the end of this file). The rest
//! of this header is the comparison with libRadtran, now recorded as `comparison` rows.
//!
//! The fixture is generated by `tools/gen_pyspectral_oracle.py` from pyspectral's `rayleigh_only`
//! look-up table (Zenodo DOI 10.5281/zenodo.1288441, CC-BY-4.0), which tabulates libRadtran DISORT
//! runs over a black surface on the US Standard profile. DISORT is a discrete-ordinate solver and
//! ours is a photon Monte Carlo with a next-event estimator: they share no line, no method and no
//! author, so where they agree the agreement is evidence.
//!
//! **The table is not the pure Rayleigh atmosphere its name suggests, and finding that out was the
//! substance of this comparison.** `rayleigh_only` is a value of pyspectral's *`aerosol_type`*
//! argument — its siblings are `marine_clean_aerosol` and the rest — so it says there is no aerosol,
//! not that there is no molecular absorption. The atmosphere is `us-standard`, whose profile carries
//! the standard ozone column, and libRadtran does not drop it unless the input deck says so.
//!
//! Three measurements say the same thing, and the third is a prediction rather than a fit:
//!
//! 1. Against a conservative Rayleigh slab at the Bodhaine et al. (1999) optical depth the table
//!    reads **low**, by 1.6 % at 400 nm rising to **16.5 % at 600 nm** and falling again to 2.3 % at
//!    800 nm. A wrong `τ` model or a wrong phase function would not put its maximum at 600 nm; the
//!    Chappuis band of ozone peaks at 602 nm.
//! 2. One scalar per wavelength — an absorber *above* the scattering layer, so a two-way
//!    `exp(−τ₃·(1/μ_s + 1/μ_v))` — collapses that to a flat **0.7–0.9 % RMS at every wavelength over
//!    all 64 geometries**, and the recovered amplitude traces the Chappuis band with its maximum at
//!    600 nm and roughly a tenth of that at 400 and 800 nm.
//! 3. Fitted on the *low* air-mass half of the grid, that same scalar predicts the *high* air-mass
//!    half to 0.8–1.1 % RMS, and the two halves agree on its value to 4–7 % wherever the band is
//!    strong. A one-parameter fit can absorb almost anything within the set it was fitted on; it
//!    cannot predict out of sample unless the functional form is right.
//!
//! So the number the comparison records is **sub-1 % agreement in angular shape between our
//! Monte Carlo and DISORT, at eight wavelengths and 64 sun/view geometries each**, with `τ_R` taken
//! from Bodhaine rather than fitted and one physically-interpretable scalar for the ozone the table
//! never mentions. At 600 000 photons our own seed-to-seed scatter is 0.17–0.80 % RMS, so a good
//! part of what is left is our statistics rather than a difference between the two solvers.
//!
//! Neither side carries polarization — DISORT here is scalar and so are we — so the several-percent
//! vector/scalar difference of real Rayleigh scattering cancels in this comparison. It is a check of
//! one scalar solver against another, not a claim about a polarized measurement.

#![allow(clippy::expect_used)] // a malformed fixture is a broken generator, and should stop the run
#![allow(clippy::cast_precision_loss)] // the counts are 24, 40 and 64

use spacelab_earthvision::{Atmosphere, PhaseFunction, path_reflectance};

/// Enough that our own scatter sits well inside the tolerances below; see the seed study in the
/// module docs.
const PHOTONS: u32 = 250_000;
const SEED: u64 = 20_260_815;

/// `1/μ_s + 1/μ_v` runs from 2.0 to 5.0 over the grid, but the table's axes are *secants* on an
/// uneven grid, so no threshold halves it: this one gives 24 points below and 40 above.
const AIR_MASS_SPLIT: f64 = 3.05;

struct Row {
    wavelength_nm: f64,
    tau_rayleigh: f64,
    mu_sun: f64,
    mu_view: f64,
    azimuth_deg: f64,
    reflectance: f64,
}

impl Row {
    /// The slant path through everything above the scattering layer, down and back up.
    fn air_mass(&self) -> f64 {
        1.0 / self.mu_sun + 1.0 / self.mu_view
    }
}

fn fixture() -> Vec<Row> {
    let text = std::fs::read_to_string("tests/fixtures/pyspectral_rayleigh.txt")
        .expect("tests/fixtures/pyspectral_rayleigh.txt — see tools/gen_pyspectral_oracle.py");
    text.lines()
        .filter(|line| !line.starts_with('#') && !line.trim().is_empty())
        .map(|line| {
            let v: Vec<f64> = line
                .split_whitespace()
                .map(|f| f.parse().expect("fixture column is not a number"))
                .collect();
            assert_eq!(v.len(), 6, "fixture row has {} columns, want 6", v.len());
            Row {
                wavelength_nm: v[0],
                tau_rayleigh: v[1],
                mu_sun: v[2],
                mu_view: v[3],
                azimuth_deg: v[4],
                reflectance: v[5],
            }
        })
        .collect()
}

/// Our conservative Rayleigh slab at the Bodhaine depth — no fitted parameter enters here.
fn ours(row: &Row) -> f64 {
    let atmosphere = Atmosphere {
        optical_depth: row.tau_rayleigh,
        single_scattering_albedo: 1.0,
        phase: PhaseFunction::Rayleigh,
    };
    path_reflectance(
        &atmosphere,
        row.mu_sun,
        row.mu_view,
        row.azimuth_deg.to_radians(),
        PHOTONS,
        SEED,
    )
}

/// `(air mass, our reflectance, the table's)` for one wavelength, in the fixture's order.
fn triples(rows: &[Row], wavelength_nm: f64) -> Vec<(f64, f64, f64)> {
    let group: Vec<&Row> = rows
        .iter()
        .filter(|r| (r.wavelength_nm - wavelength_nm).abs() < 1e-9)
        .collect();
    assert_eq!(
        group.len(),
        64,
        "{wavelength_nm} nm has {} rows",
        group.len()
    );
    group
        .iter()
        .map(|r| (r.air_mass(), ours(r), r.reflectance))
        .collect()
}

fn rms(points: &[(f64, f64, f64)], ozone_depth: f64) -> f64 {
    let sum: f64 = points
        .iter()
        .map(|&(air, ours, table)| {
            let relative = ours * libm::exp(-ozone_depth * air) / table - 1.0;
            relative * relative
        })
        .sum();
    libm::sqrt(sum / points.len() as f64)
}

/// The single absorber depth that best explains a set, by golden-section search on a unimodal
/// residual. The bracket's upper end is far above any plausible Chappuis slant depth.
fn fit_ozone_depth(points: &[(f64, f64, f64)]) -> f64 {
    let (mut low, mut high) = (0.0_f64, 0.2_f64);
    for _ in 0..60 {
        let (a, b) = (low + (high - low) / 3.0, high - (high - low) / 3.0);
        if rms(points, a) < rms(points, b) {
            high = b;
        } else {
            low = a;
        }
    }
    f64::midpoint(low, high)
}

const WAVELENGTHS_NM: [f64; 8] = [400.0, 450.0, 500.0, 550.0, 600.0, 650.0, 700.0, 800.0];

/// `ours · exp(−d · air mass) / table − 1` at each point: the relative distance once an absorber of
/// slant depth `d` sits above the scattering layer.
fn residuals(points: &[(f64, f64, f64)], ozone_depth: f64) -> Vec<f64> {
    points
        .iter()
        .map(|&(air, ours, table)| ours * libm::exp(-ozone_depth * air) / table - 1.0)
        .collect()
}

/// One `comparison | ...` row of `tools/compare.py`, for relative distances.
fn comparison_row(quantity: &str, distances: &[f64]) {
    let max = distances.iter().fold(0.0_f64, |a, d| a.max(d.abs()));
    let rms = libm::sqrt(distances.iter().map(|d| d * d).sum::<f64>() / distances.len() as f64);
    println!(
        "comparison | pyspectral | LUT v1.0.1 | {quantity} | 1 | {} | {max:.3e} | {rms:.3e}",
        distances.len()
    );
}

/// The distance in angular shape, one fitted ozone slant depth per wavelength (finding 2 above).
/// The fitted depths are printed: the Chappuis band puts their maximum at 600 nm.
#[test]
#[ignore = "comparator: the distance to pyspectral, not a verdict"]
fn angular_shape_distance_to_pyspectral() {
    let rows = fixture();
    let mut distances = Vec::new();
    for wavelength in WAVELENGTHS_NM {
        let points = triples(&rows, wavelength);
        let depth = fit_ozone_depth(&points);
        println!(
            "{wavelength} nm: fitted ozone slant depth {depth:.5}, {:.2}% RMS over 64 geometries",
            100.0 * rms(&points, depth)
        );
        distances.extend(residuals(&points, depth));
    }
    comparison_row(
        "Rayleigh path reflectance, one fitted ozone depth per wavelength",
        &distances,
    );
}

/// The out-of-sample distance (finding 3 above): the depth fitted on the 24 geometries below air
/// mass [`AIR_MASS_SPLIT`] applied to the 40 above it.
#[test]
#[ignore = "comparator: the distance to pyspectral, not a verdict"]
fn out_of_sample_distance_to_pyspectral() {
    let rows = fixture();
    let mut distances = Vec::new();
    for wavelength in WAVELENGTHS_NM {
        let points = triples(&rows, wavelength);
        let (near, far): (Vec<_>, Vec<_>) = points
            .into_iter()
            .partition(|&(air, ..)| air < AIR_MASS_SPLIT);
        assert!(
            near.len() == 24 && far.len() == 40,
            "the air-mass split is {}/{}, not 24/40 — the fixture's geometry grid changed",
            near.len(),
            far.len()
        );
        distances.extend(residuals(&far, fit_ozone_depth(&near)));
    }
    comparison_row(
        "Rayleigh path reflectance above air mass 3.05, ozone fitted below it",
        &distances,
    );
}

/// The distance with no absorber at all (finding 1 above), at the Chappuis maximum and off the band.
#[test]
#[ignore = "comparator: the distance to pyspectral, not a verdict"]
fn distance_to_pyspectral_without_the_ozone() {
    let rows = fixture();
    for wavelength in [600.0, 800.0] {
        comparison_row(
            &format!("Rayleigh path reflectance at {wavelength} nm, no absorber"),
            &residuals(&triples(&rows, wavelength), 0.0),
        );
    }
}

/// Independent streams per geometry, as `aeronet_measured_atmosphere` draws them.
const SEEDS: u64 = 3;
/// Photons per stream.
const GATE_PHOTONS: u32 = 100_000;

/// (G3) The Monte Carlo path reflectance of a conservative Rayleigh slab against the transfer
/// equation, at the 512 geometries and depths of the libRadtran table.
///
/// `fixtures/rayleigh_doubling.txt` is `derivations/slab_doubling.jl`'s doubling-and-adding
/// solution: Rayleigh's `p` has azimuthal orders 0–2 only, which `derivations/slab_doubling.mac`
/// derives by integration, so the series is exact; against 128 nodes and a start of `2⁻⁴⁰`, the 64
/// nodes and `2⁻³⁴` used move no value at the deepest or the shallowest depth by more than 5.4e-10.
/// Each point is estimated at [`SEEDS`] streams, so it carries its own standard error, and two
/// statistics of the same kind are compared as in `aeronet_measured_atmosphere`: the RMS relative
/// bias must sit within 1.6 times the RMS relative standard error (measured 0.96), and the mean bias
/// within 4 standard errors of a mean (measured 2.54 on these streams, 0.91 on a second set drawn to
/// check it).
#[test]
fn the_rayleigh_path_reflectance_meets_the_doubling_solution() {
    let text = std::fs::read_to_string("tests/fixtures/rayleigh_doubling.txt")
        .expect("tests/fixtures/rayleigh_doubling.txt — see derivations/slab_doubling.jl");
    let (mut bias, mut noise) = (Vec::new(), Vec::new());
    for (point, line) in text
        .lines()
        .filter(|line| !line.starts_with('#') && !line.trim().is_empty())
        .enumerate()
    {
        let v: Vec<f64> = line
            .split_whitespace()
            .map(|f| f.parse().expect("fixture column is not a number"))
            .collect();
        let (tau, mu_sun, mu_view, azimuth_deg, reference) = (v[1], v[2], v[3], v[4], v[5]);
        let atmosphere = Atmosphere {
            optical_depth: tau,
            single_scattering_albedo: 1.0,
            phase: PhaseFunction::Rayleigh,
        };
        let draws: Vec<f64> = (0..SEEDS)
            .map(|draw| {
                let seed = SEED
                    .wrapping_add((point as u64).wrapping_mul(0xff51_afd7_ed55_8ccd))
                    .wrapping_add(draw.wrapping_mul(0x9e37_79b9_7f4a_7c15));
                path_reflectance(
                    &atmosphere,
                    mu_sun,
                    mu_view,
                    azimuth_deg.to_radians(),
                    GATE_PHOTONS,
                    seed,
                )
            })
            .collect();
        let count = draws.len() as f64;
        let mean = draws.iter().sum::<f64>() / count;
        let variance = draws.iter().map(|d| (d - mean) * (d - mean)).sum::<f64>() / (count - 1.0);
        bias.push(mean / reference - 1.0);
        noise.push(libm::sqrt(variance / count) / reference);
    }
    assert_eq!(bias.len(), 512, "the fixture lost geometries");
    let n = bias.len() as f64;
    let rms_bias = libm::sqrt(bias.iter().map(|b| b * b).sum::<f64>() / n);
    let rms_noise = libm::sqrt(noise.iter().map(|s| s * s).sum::<f64>() / n);
    let mean_bias = bias.iter().sum::<f64>() / n;
    let lean = mean_bias.abs() / (rms_noise / libm::sqrt(n));
    println!(
        "MEASURED Rayleigh n {n}  bias rms {rms_bias:.3e} mean {mean_bias:+.3e}  noise rms \
         {rms_noise:.3e}  ratio {:.2}  lean {lean:.2}",
        rms_bias / rms_noise
    );
    assert!(
        rms_bias < 1.6 * rms_noise,
        "RMS bias {rms_bias:.3e} against RMS standard error {rms_noise:.3e}"
    );
    assert!(
        lean < 4.0,
        "the mean bias leans by {lean:.2} standard errors"
    );
}
